// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != c.owner());
        vm.assume(newOwner != c.owner());
        vm.prank(actor);
        try c.transferOwnership(newOwner) {} catch {}
        assertTrue(c.owner() == address(0));
    }
}
